// bunku-mascot.js
// Drop-in canvas mascot — two animations, same canvas, random human-like behavior.
// Works on iOS, Android, all browsers. No HTML modification needed.

(function () {
  "use strict";

  // ── ANIMATION CONFIGS ────────────────────────────────────
  const ANIM_1 = {
    label: "wave",
    fps: 15,

    width: 638,
    height: 360,
    frames: [
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
    ],
  };

  const ANIM_2 = {
    label: "carrot",
    fps: 24,
    width: 738,
    height: 460,
    frames: [
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
      "data:image/webp;base64,",
    ],
  };

  const IDLE_MIN_MS = 3500;
  const IDLE_MAX_MS = 7000;
  const GREET_DELAY = 1500; // first play after load
  const HOVER_DELAY = 350; // ms before reacting to hover
  const WAVE_WEIGHT = 0.55; // probability of waving vs carrot
  const MAX_HISTORY = 2; // prevent same animation repeating too often
  // ────────────────────────────────────────────────────────

  const canvas = document.getElementById("bunku-mascot");
  if (!canvas || canvas.tagName !== "CANVAS") {
    console.warn('bunku-mascot: no <canvas id="bunku-mascot"> found.');
    return;
  }

  const ctx = canvas.getContext("2d");
  const ANIMS = [ANIM_1, ANIM_2];

  // Loaded image banks — images[animIdx][frameIdx]
  const imageBank = ANIMS.map((a) => new Array(a.frames.length));
  let totalLoaded = 0;
  const totalFrames = ANIMS.reduce((s, a) => s + a.frames.length, 0);

  // Playback state
  let playing = false;
  let activeAnim = null; // current ANIM object
  let activeIdx = 0; // index into ANIMS
  let frame = 0;
  let interval = 0;
  let lastTime = null;
  let rafHandle = null;
  let idleTimer = null;
  let hoverTimer = null;
  const history = [];

  // ── Preload all frames from both animations ──
  function preload() {
    ANIMS.forEach((anim, ai) => {
      anim.frames.forEach((src, fi) => {
        const img = new Image();
        img.onload = img.onerror = () => {
          imageBank[ai][fi] = img;
          if (++totalLoaded === totalFrames) onReady();
        };
        img.src = src;
      });
    });
  }

  function onReady() {
    drawFrame(0, 0);
    schedulePlay(GREET_DELAY);
  }

  // ── Draw one frame of the given animation ──
  function drawFrame(animIdx, frameNum) {
    const img = imageBank[animIdx][frameNum];
    if (!img || !img.complete) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const anim = ANIMS[animIdx];
    const targetWidth = anim.width || canvas.width;
    const targetHeight = anim.height || canvas.height;
    const imgAspect = img.naturalWidth / img.naturalHeight;
    const targetAspect = targetWidth / targetHeight;

    let drawWidth, drawHeight, offsetX, offsetY;

    if (imgAspect > targetAspect) {
      // Image is wider — fit to height
      drawHeight = targetHeight;
      drawWidth = drawHeight * imgAspect;
      offsetX = (canvas.width - drawWidth) / 2;
      offsetY = (canvas.height - drawHeight) / 2;
    } else {
      // Image is taller — fit to width
      drawWidth = targetWidth;
      drawHeight = drawWidth / imgAspect;
      offsetX = (canvas.width - drawWidth) / 2;
      offsetY = (canvas.height - drawHeight) / 2;
    }

    ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
  }

  // ── Smart random pick — avoids same anim repeating MAX_HISTORY times ──
  function pickAnim() {
    if (
      history.length >= MAX_HISTORY &&
      history
        .slice(-MAX_HISTORY)
        .every((v) => v === history[history.length - 1])
    ) {
      return history[history.length - 1] === 0 ? 1 : 0;
    }
    return Math.random() < WAVE_WEIGHT ? 0 : 1;
  }

  // ── Human-like idle delay with occasional quick follow-ups ──
  function randomIdle() {
    const base = IDLE_MIN_MS + Math.random() * (IDLE_MAX_MS - IDLE_MIN_MS);
    return Math.random() < 0.18 ? base * 0.35 : base;
  }

  function schedulePlay(delay) {
    clearTimeout(idleTimer);
    idleTimer = setTimeout(
      playOnce,
      delay !== undefined ? delay : randomIdle(),
    );
  }

  // ── Play a single animation pass then return to idle ──
  function playOnce(forceAnimIdx) {
    if (playing) return;

    activeIdx = forceAnimIdx !== undefined ? forceAnimIdx : pickAnim();
    activeAnim = ANIMS[activeIdx];
    interval = 1000 / activeAnim.fps;

    history.push(activeIdx);
    if (history.length > MAX_HISTORY + 1) history.shift();

    playing = true;
    frame = 0;
    lastTime = null;
    rafHandle = requestAnimationFrame(tick);
  }

  function tick(ts) {
    if (lastTime === null) lastTime = ts;
    const elapsed = ts - lastTime;

    if (elapsed >= interval) {
      lastTime = ts - (elapsed % interval);
      drawFrame(activeIdx, frame);
      frame++;

      if (frame >= activeAnim.frames.length) {
        playing = false;
        cancelAnimationFrame(rafHandle);
        drawFrame(0, 0); // return to neutral pose (frame 0 of wave anim)
        schedulePlay();
        return;
      }
    }
    rafHandle = requestAnimationFrame(tick);
  }

  // ── Interactions ─────────────────────────────────────────

  // Click / tap → wave immediately
  canvas.style.cursor = "pointer";
  canvas.addEventListener("click", () => {
    if (playing) return;
    clearTimeout(idleTimer);
    clearTimeout(hoverTimer);
    playOnce(0);
  });

  // Hover → carrot animation after a natural pause
  canvas.addEventListener("mouseenter", () => {
    if (playing) return;
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(() => {
      if (!playing) {
        clearTimeout(idleTimer);
        playOnce(1);
      }
    }, HOVER_DELAY);
  });

  canvas.addEventListener("mouseleave", () => {
    clearTimeout(hoverTimer);
  });

  // ── Pause when tab is hidden (saves CPU / battery) ──
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      cancelAnimationFrame(rafHandle);
      clearTimeout(idleTimer);
      clearTimeout(hoverTimer);
    } else if (!playing) {
      schedulePlay(1000);
    }
  });

  preload();
})();
